const CONFIG={whatsapp:'573000000000',currency:'COP',campaign:'Esenciales 2026'};
const productNames=['Camisa Lino','Polo Esencial','Blusa Atemporal','Pantalón Recto','Chaqueta Ligera','Camiseta Algodón','Vestido Fluido','Sudadera Urbana','Delantal Taller','Uniforme Brisa','Conjunto Infantil','Jogger Diario'];
const palettes=['#d7a58b','#9db4aa','#e2c56d','#c9d6cf','#b5a791','#c3a5aa','#a7b9c4','#d6c5a7'];
const categories=['Mujer','Hombre','Dotación','Infantil']; const materials=['Algodón','Lino','Dril','Mezcla suave'];
const products=Array.from({length:318},(_,i)=>{const c=categories[i%4], tag=i%9===0?'Oferta':i%5===0?'Tendencia':i%7===0?'Nuevo':'Recomendado';return {id:i+1,ref:`MPM-${String(i+1).padStart(4,'0')}`,name:productNames[i%productNames.length],category:c,material:materials[i%4],price:49000+(i%6)*12000,tag,availability:i%11===0?'Bajo pedido':'Disponible',sizes:['S','M','L','XL'],colors:['Natural','Terracota','Verde bosque'],color:palettes[i%palettes.length],tilt:`${(i%5-2)*3}deg`}});
let state={query:'',categories:[],availability:[],tags:[],size:'',visible:9,cart:JSON.parse(localStorage.getItem('mpm-cart')||'[]')};
const $=s=>document.querySelector(s); const money=n=>new Intl.NumberFormat('es-CO',{style:'currency',currency:CONFIG.currency,maximumFractionDigits:0}).format(n);
function filtered(){return products.filter(p=>{let q=state.query.toLowerCase();return (!q||[p.name,p.ref,p.material,p.category].join(' ').toLowerCase().includes(q))&&(!state.categories.length||state.categories.includes(p.category))&&(!state.availability.length||state.availability.includes(p.availability))&&(!state.tags.length||state.tags.includes(p.tag))&&(!state.size||p.sizes.includes(state.size))})}
function renderProducts(){let list=filtered(), shown=list.slice(0,state.visible);$('#results-count').textContent=list.length;$('#product-grid').innerHTML=shown.length?shown.map(p=>`<button class="product" data-id="${p.id}" aria-label="Ver ${p.name}, ${p.ref}"><div class="product-image" style="--product-color:${p.color};--tilt:${p.tilt}"><span>${p.ref}</span>${p.tag!=='Recomendado'?`<i>${p.tag}</i>`:''}</div><div class="product-info"><div><b>${p.name}</b><span>${money(p.price)}</span></div><small>${p.category} · ${p.material}</small></div></button>`).join(''):'<p class="empty">No encontramos prendas con esos filtros. Prueba otra palabra o limpia los filtros.</p>';$('#load-more').hidden=shown.length>=list.length; renderChips()}
function renderChips(){let chips=[...state.categories,...state.availability,...state.tags,state.size].filter(Boolean);$('#active-filters').innerHTML=chips.map(x=>`<span class="chip">${x}</span>`).join('')}
function renderCart(){let total=state.cart.reduce((sum,i)=>sum+i.price*i.qty,0);$('#cart-count').textContent=state.cart.reduce((s,i)=>s+i.qty,0);$('#cart-items').innerHTML=state.cart.length?state.cart.map((i,n)=>`<div class="cart-item"><div class="cart-thumb" style="--product-color:${i.color}"></div><div><b>${i.name}</b><small>${i.ref} · ${i.size} · ${i.selectedColor}</small><small>${i.qty} × ${money(i.price)} = ${money(i.price*i.qty)}</small></div><button data-remove="${n}" aria-label="Eliminar ${i.name}">Eliminar</button></div>`).join('')+`<p style="text-align:right;font-weight:700">Total referencial: ${money(total)}</p>`:'<p class="empty">Tu bolsa está vacía. Agrega una prenda para pedir asesoría.</p>';$('#order-form').style.display=state.cart.length?'block':'none';localStorage.setItem('mpm-cart',JSON.stringify(state.cart))}
function openProduct(id){let p=products.find(x=>x.id===+id);$('#product-detail').innerHTML=`<div class="detail"><div class="detail-image" style="--product-color:${p.color}"></div><div class="detail-copy"><span class="ref">${p.ref} · ${p.category}</span><h2>${p.name}</h2><b>${money(p.price)} <small style="font-weight:400">precio referencial</small></b><p>Prenda de demostración en ${p.material.toLowerCase()}, pensada para comodidad y uso diario. Confirma con nuestro equipo la disponibilidad final.</p><label>Talla</label><div class="selection" id="sizes">${p.sizes.map((s,i)=>`<button class="${i===1?'selected':''}" data-value="${s}">${s}</button>`).join('')}</div><label>Color</label><div class="selection" id="colors">${p.colors.map((c,i)=>`<button class="${i===0?'selected':''}" data-value="${c}">${c}</button>`).join('')}</div><button class="button primary" id="add-product">Agregar a solicitud →</button></div></div>`;let d=$('#product-dialog');d.showModal();let choose=sel=>$(sel).addEventListener('click',e=>{if(e.target.tagName==='BUTTON'){[...e.currentTarget.children].forEach(b=>b.classList.remove('selected'));e.target.classList.add('selected')}});choose('#sizes');choose('#colors');$('#add-product').onclick=()=>{let item={...p,size:$('#sizes .selected').dataset.value,selectedColor:$('#colors .selected').dataset.value,qty:1};let found=state.cart.find(x=>x.id===item.id&&x.size===item.size&&x.selectedColor===item.selectedColor);found?found.qty++:state.cart.push(item);renderCart();d.close();openCart()}}
function openCart(){$('#cart-drawer').classList.add('open');$('#scrim').classList.add('show');$('#cart-drawer').setAttribute('aria-hidden','false')};function closeCart(){$('#cart-drawer').classList.remove('open');$('#scrim').classList.remove('show');$('#cart-drawer').setAttribute('aria-hidden','true')}
$('#search').addEventListener('input',e=>{state.query=e.target.value;state.visible=9;renderProducts()});document.querySelectorAll('.filters input').forEach(i=>i.addEventListener('change',()=>{state.categories=[...document.querySelectorAll('[name=category]:checked')].map(x=>x.value);state.availability=[...document.querySelectorAll('[name=availability]:checked')].map(x=>x.value);state.tags=[...document.querySelectorAll('[name=tag]:checked')].map(x=>x.value);state.visible=9;renderProducts()}));document.querySelectorAll('.size-buttons button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.size-buttons button').forEach(x=>x.classList.remove('selected'));if(state.size===b.dataset.size)state.size='';else{state.size=b.dataset.size;b.classList.add('selected')}state.visible=9;renderProducts()});$('#clear-filters').onclick=()=>{state={...state,categories:[],availability:[],tags:[],size:'',query:''};document.querySelectorAll('.filters input').forEach(x=>x.checked=false);document.querySelectorAll('.size-buttons button').forEach(x=>x.classList.remove('selected'));$('#search').value='';renderProducts()};$('#product-grid').onclick=e=>{let b=e.target.closest('.product');if(b)openProduct(b.dataset.id)};$('#load-more').onclick=()=>{state.visible+=9;renderProducts()};document.querySelectorAll('.category').forEach(b=>b.onclick=()=>{state.categories=[b.dataset.category];document.querySelectorAll('[name=category]').forEach(x=>x.checked=x.value===b.dataset.category);location.hash='catalogo';renderProducts()});$('[data-filter-tag="Tendencia"]').onclick=()=>{state.tags=['Tendencia'];document.querySelector('[name=tag][value=Tendencia]').checked=true;location.hash='catalogo';renderProducts()};$('#filter-toggle').onclick=()=>{let f=$('#filters'),expanded=f.classList.toggle('open');$('#filter-toggle').setAttribute('aria-expanded',expanded)};$('#open-cart').onclick=openCart;$('.close-cart').onclick=closeCart;$('#scrim').onclick=closeCart;$('.close-dialog').onclick=()=>$('#product-dialog').close();$('#cart-items').onclick=e=>{let n=e.target.dataset.remove;if(n!==undefined){state.cart.splice(+n,1);renderCart()}};$('#order-form').onsubmit=e=>{e.preventDefault();if(!state.cart.length)return;let form=new FormData(e.currentTarget);if(!e.currentTarget.checkValidity()){e.currentTarget.reportValidity();return}let lines=state.cart.map(i=>`• ${i.name} (${i.ref}) — ${i.size}, ${i.selectedColor}, x${i.qty}`).join('\n');let text=`Hola MPM, deseo solicitar asesoría para este pedido:\n${lines}\n\nTotal referencial: ${money(state.cart.reduce((s,i)=>s+i.price*i.qty,0))}\n\nContacto: ${form.get('name')} | ${form.get('phone')} | ${form.get('city')}${form.get('company')?` | Empresa: ${form.get('company')}`:''}${form.get('comment')?`\nComentario: ${form.get('comment')}`:''}\nAutorizo el tratamiento de datos para atender mi solicitud.`;window.open(`https://wa.me/${CONFIG.whatsapp}?text=${encodeURIComponent(text)}`,'_blank','noopener');$('#form-error').textContent='Solicitud preparada: completa el envío en WhatsApp.'};$('#admin-link').onclick=e=>{e.preventDefault();$('#admin').hidden=false;document.body.style.overflow='hidden'};$('#close-admin').onclick=()=>{$('#admin').hidden=true;document.body.style.overflow=''};$('#save-campaign').onclick=()=>{$('#save-status').textContent='Cambios guardados localmente (demostración).'};renderProducts();renderCart();
